std::vector<OrgApacheFelixHttpProperties> createOrgApacheFelixHttpPropertiesVectorFromJsonString(const std::string& json)
{
    std::stringstream sstream(json);
    boost::property_tree::ptree pt;
    boost::property_tree::json_parser::read_json(sstream,pt);

    auto vec = std::vector<OrgApacheFelixHttpProperties>();
    for (const auto& child: pt) {
        vec.emplace_back(OrgApacheFelixHttpProperties(child.second));
    }

    return vec;
}

